"""Mutation guard: git_shim. Declared here, run by scripts/mutation_check.py (#866)."""
from mutation_types import Guard, Mutation  # noqa: F401

# #1790. The git shim. Each mutation breaks ONE rule, and the selftest must notice it from the OUTSIDE: a real git command on a real repository,
# then a look at what moved. `narrow_with` runs each mutant on only the case its `expects` names.
GUARD = Guard(
    name='git_shim',
    subject='git-shim/git',
    selftest="scripts/git_shim_selftest.py",
    needs=("scripts/fixture_git.py", "git-shim/git", "hooks/scripts/session-start.sh", "hooks/scripts/lib"),
    narrow_with="--match",
    mutations=(
        Mutation('add --all is not refused', 'if seen all; then RULE="git add --all', 'if false; then RULE="git add --all', 'add --all and every prefix'),
        Mutation('a long option is matched only in full, so --al and --ha pass', 'case "$c" in "$name"*) SEEN="$SEEN$c "; hit=1 ;; esac', 'case "$c" in "$name") SEEN="$SEEN$c "; hit=1 ;; esac', 'add --all and every prefix'),
        Mutation('pathspec magic is allowed', '    :*) BADWHY="pathspec magic ($p) cannot be judged"; return 1 ;;', '    :*) ;;', 'a pathspec that is not a plain relative path'),
        Mutation('an absolute pathspec is allowed', '      rel="$(abs_inside "$p")"', '      rel="x"', 'a pathspec that is not a plain relative path'),
        Mutation('a glob pathspec is allowed', '    *"*"*|*"?"*|*"["*) BADWHY="a glob ($p) can match the whole tree"; return 1 ;;', '    *"*"*) ;;', 'a pathspec that is not a plain relative path'),
        Mutation('the repository root is allowed', 'if [ -z "$n" ]; then BADWHY="$p is the repository root"; return 1; fi', 'if false; then BADWHY="$p is the repository root"; return 1; fi', 'add of the repository root is refused in every spelling'),
        Mutation('a path that leaves the repository is allowed', 'if [ "$n" = "OUT" ]; then BADWHY="$p leaves the repository"; return 1; fi', 'if false; then BADWHY="$p leaves the repository"; return 1; fi', 'a pathspec that is not a plain relative path'),
        Mutation('the prefix is ignored, so `add .` in a subdirectory is refused', 'n="$(norm "$PREFIX" "$p")"', 'n="$(norm "" "$p")"', 'add near-misses run'),
        Mutation('--pathspec-from-file is not refused', 'if [ "$PFILE" = 1 ]; then RULE=', 'if false; then RULE=', 'a pathspec that is not a plain relative path'),
        Mutation('--no-<option> does not negate a dry run', '            no-?*) rest="${name#no-}"; for c in $longs; do case "$c" in "$rest"*) SEEN="${SEEN/ $c / }"; hit=1 ;; esac; done ;;', '            no-?*) ;;', 'negates a dry run'),
        Mutation('--verify does not negate --no-verify', '            verify) SEEN="${SEEN/ no-verify / }"; hit=1 ;;', '            verify) hit=1 ;;', 'negates a dry run'),
        Mutation('add --dry-run is refused', '    add)\n      seen dry-run && return 0', '    add)\n      :', 'add near-misses run'),
        Mutation('add -u is refused', '      seen update && return 0; seen patch', '      seen patch', 'add near-misses run'),
        Mutation('reset --hard is not refused', 'if seen hard; then', 'if false; then', 'reset --hard and its prefixes'),
        Mutation('checkout --force is not refused', 'if seen force; then RULE="git checkout --force', 'if false; then RULE="git checkout --force', 'checkout and switch that discard work'),
        Mutation('checkout pathspecs are not checked', '      paths_plain "git checkout" || return 1 ;;', '      : ;;', 'checkout and switch that discard work'),
        Mutation('switch --force is not refused', 'if seen force || seen discard-changes; then', 'if false; then', 'checkout and switch that discard work'),
        Mutation('restore --staged . is refused', 'if seen worktree || ! seen staged; then paths_plain', 'if true; then paths_plain', 'restore --staged passes'),
        Mutation('restore --staged --worktree . is allowed', 'if seen worktree || ! seen staged; then paths_plain', 'if ! seen staged; then paths_plain', 'restore of the working tree root is refused'),
        Mutation('clean --force is not refused', 'if seen force; then RULE="git clean --force', 'if false; then RULE="git clean --force', 'clean --force in every spelling'),
        Mutation('a clean dry run is refused', '    clean)\n      seen dry-run && return 0', '    clean)\n      :', 'clean dry runs pass'),
        Mutation('requireForce=false is not checked', 'if ! seen interactive && [ "$("$real" "${GLOBALS[@]}" config --type=bool --get clean.requireForce 2>/dev/null)" = "false" ]; then', 'if false; then', 'requireForce is off'),
        Mutation('rm of the root is not refused', 'if is_root_path "$p"; then RULE="git rm of the repository', 'if false; then RULE="git rm of the repository', 'stash drop and clear'),
        Mutation('rm --cached is refused', '      seen cached && return 0; seen dry-run && return 0', '      seen dry-run && return 0', 'stash drop and clear'),
        Mutation('stash clear is not refused', 'case "${PATHS[0]:-}" in drop|clear) RULE=', 'case "${PATHS[0]:-}" in drop) RULE=', 'stash drop and clear'),
        Mutation('checkout-index -f is not refused', 'if seen force; then RULE="git checkout-index', 'if false; then RULE="git checkout-index', 'stash drop and clear'),
        Mutation('read-tree --reset is refused without -u', 'if seen reset && seen update; then', 'if seen reset; then', 'stash drop and clear'),
        Mutation('git config core.hooksPath is not refused', 'if ci_match "$x" "*core.hookspath*" ||', 'if ci_match "$x" "*core.hookspathXX*" ||', 'git config of core.hooksPath or include'),
        Mutation('git config include.path is not refused', 'ci_match "$x" "*include.path*"', 'ci_match "$x" "*includeXX*"', 'git config of core.hooksPath or include'),
        Mutation('config keys are matched case-sensitively', 'shopt -s nocasematch;', ':;', 'ALLOWLIST of exact keys'),
        Mutation('GIT_CONFIG_* in the environment is not refused', 'for v in $(compgen -e GIT_CONFIG_); do', 'for v in; do', 'a GIT_CONFIG_* variable'),
        Mutation('--no-verify is not refused', 'if seen no-verify; then RULE="--no-verify', 'if false; then RULE="--no-verify', '--no-verify in every spelling'),
        Mutation('commit -n is not read as --no-verify', '    commit) echo "n=no-verify" ;;', '    commit) echo "" ;;', '--no-verify in every spelling'),
        Mutation('pull, am, cherry-pick and revert are not checked for --no-verify', '    commit|push|merge|rebase|pull|am|cherry-pick|revert) echo "no-verify" ;;', '    commit|push|merge|rebase) echo "no-verify" ;;', '--no-verify in every spelling'),
        Mutation('an attached value (-uno) is read as -n', '    commit) echo "uS" ;; merge)', '    commit) echo "S" ;; merge)', 'commit near-misses run'),
        Mutation('the value of commit -m is read as an option', '    commit) echo "mFCct" ;;', '    commit) echo "FCct" ;;', 'commit near-misses run'),
        Mutation('-- does not end the options', '      --) seen_dd=1 ;;', '      --) ;;', 'add near-misses run'),
        Mutation('a git alias is not read', 'val="$("$real" "${GLOBALS[@]}" config --get "alias.$SUB" 2>/dev/null)"; rc=$?', 'val=""; rc=1', 'a git alias is expanded'),
        Mutation('a shell alias that mentions git is allowed', 'if ci_match "$val" "*git*"; then RULE="the shell alias', 'if false; then RULE="the shell alias', 'a shell alias that mentions git'),
        Mutation('an alias with a quote is allowed', '      *\\\'*|*\\"*|*\\\\*) RULE="the alias alias.$SUB holds a quote', '      *NOPE*) RULE="the alias alias.$SUB holds a quote', 'an alias with a quote'),
        Mutation('an alias chain of any depth is followed', 'if [ "$depth" -gt 5 ]; then RULE="an alias chain', 'if false; then RULE="an alias chain', 'an alias with a quote'),
        Mutation('the shim finds itself as the real git', '  [ "$dd" = "$self_dir" ] && continue', '  :', 'does not loop'),
        Mutation('the escape variable is not read', 'if [ "${RAILS_FLOW_GIT_OK:-}" = 1 ]; then', 'if [ "${RAILS_FLOW_GIT_OK:-}" = 2 ]; then', 'RAILS_FLOW_GIT_OK=1 runs the real git'),
        Mutation('-C is not forwarded when finding the root', '  TOP="$("$real" "${GLOBALS[@]}" rev-parse --show-toplevel 2>/dev/null)" || TOP=""', '  TOP="$("$real" rev-parse --show-toplevel 2>/dev/null)" || TOP=""', '-C is honoured'),
        Mutation('the shim depends on tr, so a PATH without it fails open', 'ci_match() { local r;', 'ci_match() { local r; tr a a </dev/null >/dev/null 2>&1 || return 1;', 'with no tr or dirname on PATH'),
        # #1982. The GIT_CONFIG_* pairs are READ; an absolute path counts only when it is strictly inside the toplevel.
        Mutation('every GIT_CONFIG_* variable is refused on sight again, so a hermetic fixture cannot even `git init`',
                 'GIT_CONFIG_NOSYSTEM|GIT_CONFIG_COUNT|GIT_CONFIG_KEY_*|GIT_CONFIG_VALUE_*) ;;',
                 'GIT_CONFIG_NOSYSTEM|GIT_CONFIG_COUNT|GIT_CONFIG_KEY_*|GIT_CONFIG_VALUE_*) RULE="x"; refuse "${ORIG[@]}" ;;', 'a GIT_CONFIG_* variable'),
        Mutation('the key of a GIT_CONFIG_KEY_n pair is not checked, so any pair passes',
                 'if ! CFG_ALLOWED "$cfg_key"; then', 'if false; then',
                 'ALLOWLIST of exact keys'),
        Mutation('any GIT_CONFIG_GLOBAL file passes', '[ "${!v}" = /dev/null ] || {', '[ -n "${!v}" ] || {', 'a GIT_CONFIG_* variable'),
        Mutation('GIT_CONFIG_PARAMETERS and an unknown GIT_CONFIG_* name pass',
                 '    *) RULE="$v is set: it can define aliases, core.hooksPath and includes that this shim cannot read"; refuse "${ORIG[@]}" ;;', '    *) ;;',
                 'a GIT_CONFIG_* variable'),
        Mutation('a count that is not a number passes', "''|*[!0-9]*|??????*) RULE=", "''|NEVER) RULE=", 'a GIT_CONFIG_* variable'),
        Mutation('"inside the repository" is a string prefix, so a sibling directory named like it passes',
                 'case "$phys/$base" in "$TOP"/?*)', 'case "$phys/$base" in "$TOP"*)', 'STRICTLY INSIDE this repository'),
        Mutation('the directory of an absolute path is not resolved physically, so a path spelled through a symlink is refused',
                 'phys="$(cd "$dir" 2>/dev/null && pwd -P)" || return 0', 'phys="$(cd "$dir" 2>/dev/null && pwd)" || return 0', 'STRICTLY INSIDE this repository'),
        # #1982 (the coordinator's decision): the config a command may carry is an ALLOWLIST of exact keys, in all three forms.
        Mutation('an allowlisted key is matched by prefix, so `user.name.x` and `user.namex` pass',
                 'ci_match "$1" "user.name" ||', 'ci_match "$1" "user.name*" ||', 'ALLOWLIST of exact keys'),
        Mutation('the -c form is not checked, so `-c core.pager=...` passes', 'if CFG_DANGER "${ARGV[$i]}"; then', 'if false; then', 'ALLOWLIST of exact keys'),
        Mutation('the --config-env= form is not checked', 'if CFG_DANGER "${a#--config-env=}"; then', 'if false; then', 'ALLOWLIST of exact keys'),
        Mutation('the -c and --config-env checks are a denylist of two keys again, so core.pager, core.editor and credential.helper pass',
                 'CFG_DANGER() { ! CFG_ALLOWED "${1%%=*}"; }', 'CFG_DANGER() { ci_match "${1%%=*}" "core.hookspath" || ci_match "${1%%=*}" "include.*"; }', 'ALLOWLIST of exact keys'),
        Mutation('the allowlist admits every key', 'CFG_ALLOWED() {', 'CFG_ALLOWED() { return 0;', 'ALLOWLIST of exact keys'),
        Mutation('the allowlist drops commit.gpgsign, which a hermetic fixture passes with -c',
                 ' || ci_match "$1" "commit.gpgsign"', '', 'ALLOWLIST of exact keys'),
        # #1982 (decision (b)): the fixture exemption for `add`, one mutant per condition. "GIT_DIR and GIT_WORK_TREE both set" is enforced twice (by the physical resolutions and by the
        # strictly-inside checks), so it has no mutant of its own; `TMPDIR=/` is refused by the same strictly-inside pattern (`//?*` matches nothing), so it has none either.
        Mutation('the exemption is never consulted, so a fixture cannot stage its own repository', '      fixture_repo && return 0\n', '', 'stage its OWN temp repository whole'),
        Mutation('GIT_DIR need not lie inside the temp root', 'case "$gd" in "$tp"/?*) ;; *) return 1 ;; esac', ':', 'stage its OWN temp repository whole'),
        Mutation('the work tree need not lie inside the temp root', 'case "$wt" in "$tp"/?*) ;; *) return 1 ;; esac', ':', 'stage its OWN temp repository whole'),
        Mutation('"inside the temp root" is a string prefix, so a sibling directory named like it passes',
                 'case "$wt" in "$tp"/?*) ;; *) return 1 ;; esac', 'case "$wt" in "$tp"*) ;; *) return 1 ;; esac', 'stage its OWN temp repository whole'),
        Mutation('"inside the temp root" is a string prefix for GIT_DIR, so a sibling directory named like it passes',
                 'case "$gd" in "$tp"/?*) ;; *) return 1 ;; esac', 'case "$gd" in "$tp"*) ;; *) return 1 ;; esac', 'stage its OWN temp repository whole'),
        Mutation('an unset TMPDIR defaults to something that widens the temp root',
                 '  [ -n "${TMPDIR:-}" ] || return 1\n  tp="$(phys "$TMPDIR")";', '  tp="$(phys "${TMPDIR:-$GIT_WORK_TREE/..}")";', 'stage its OWN temp repository whole'),
        Mutation('TMPDIR may be HOME or an ancestor of it', 'if [ -n "$hp" ]; then case "$hp/" in "$tp"/*) return 1 ;; esac; fi', ':', 'stage its OWN temp repository whole'),
        Mutation('the work tree may be the session project or contain it', 'case "$pp/" in "$wt"/*) return 1 ;; esac', ':', 'stage its OWN temp repository whole'),
        Mutation('an unset RAILS_FLOW_PROJECT_TOP is not a refusal',
                 '  [ -n "${RAILS_FLOW_PROJECT_TOP:-}" ] || return 1\n  pp="$(phys "$RAILS_FLOW_PROJECT_TOP")"; [ -n "$pp" ] || return 1',
                 '  pp="$(phys "${RAILS_FLOW_PROJECT_TOP:-/nonexistent-x}")"', 'stage its OWN temp repository whole'),
        Mutation('the paths are resolved logically, so a symlink in temp that points at the project is not seen',
                 'phys() { ( cd "$1" 2>/dev/null && pwd -P ); }', 'phys() { ( cd "$1" 2>/dev/null && pwd ); }', 'stage its OWN temp repository whole'),
    ),
)
